// New practice examples designed around the study needs of this deck.
export const MORE_CARDS = [
{id:'g02',topic:'grammar',kind:'Form and use',q:'Analyse the verb phrase. Does it mean the action is still happening?',example:'I have lost my classroom key, so I cannot open the door.',answer:'Present perfect simple; a past event with a present result.',explain:'The form is have + past participle (lost). The loss happened before now and matters now: the key is missing. The act of losing is not continuing.',checks:['Present perfect simple: have + past participle.','Explain the present consequence.'],trap:'Not every present perfect describes an action continuing into the present.',source:'grammar'},
{id:'g03',topic:'grammar',kind:'Analyse the form',q:'Give three form points and explain the choice of voice.',example:'The new library was opened in April.',answer:'Past simple passive: was + past participle.',explain:'“Was” is the third-person singular past form of the auxiliary be. “Opened” is a past participle. The passive places the library in subject position; who opened it is not specified.',checks:['Past simple and passive.','Auxiliary was + past participle opened.','The library, rather than the agent, is the focus.'],trap:'“Past tense” alone leaves several useful form points unstated.',source:'grammar'},
{id:'g04',topic:'grammar',kind:'Form versus meaning',q:'Which answer analyses grammar rather than merely paraphrasing vocabulary?',example:'She taught evening classes for five years.\nA. She worked as a teacher.\nB. Taught is the irregular past simple of teach; the period is presented as finished.',answer:'B analyses the form and grammatical use.',explain:'A gives the lexical meaning of the action. B identifies the verb form and the way the speaker presents the time period. In a form-and-use task, make both kinds of grammatical point explicit.',checks:['Identify irregular past simple.','Explain the completed past period.'],trap:'A description of the person’s job is not a tense analysis.',source:'grammar'},
{id:'g05',topic:'grammar',kind:'Contrast two forms',q:'Which sentence accepts both “used to” and “would” for a past habit?',example:'A. I ___ live near the sea.\nB. Every summer, we ___ visit our cousins.',answer:'B accepts both. A normally takes used to.',explain:'Used to can describe past states and repeated past actions that no longer hold. Habitual would normally describes repeated actions within an established past context, not a continuing past state such as living somewhere.',checks:['Used to works with states and habits.','Habitual would works with repeated actions.'],trap:'Used to + base verb is not a past continuous form.',source:'grammar'},
{id:'g06',topic:'grammar',kind:'Repair the label',q:'Name the form of “was preparing” and explain its role.',example:'I was preparing the handouts when the printer broke.',answer:'Past continuous: was + -ing form.',explain:'The preparation was in progress around the time of the printer failure. It provides background to the shorter past-simple event. The sentence does not tell us whether the preparation was completed.',checks:['Was/were + -ing form.','An ongoing background action at a past time.'],trap:'Do not confuse an activity in progress with a repeated past habit.',source:'grammar'},
{id:'g07',topic:'grammar',kind:'Explain the article',q:'Why is there no article before “teachers”?',example:'Teachers need time to plan.',answer:'Zero article with a plural count noun used generally.',explain:'The sentence refers to teachers as a group, not an identifiable set. “The teachers need time to plan” would normally point to particular teachers known from the context.',checks:['Teachers is plural and countable.','The reference is general, not to a specific known group.'],trap:'“No article is needed” repeats the observation without explaining it.',source:'grammar'},
{id:'g08',topic:'grammar',kind:'Explain the article',q:'Explain the zero article before “confidence”.',example:'Regular practice can build confidence.',answer:'Confidence is an uncountable abstract noun used generally.',explain:'The speaker does not identify a particular instance or amount. Compare “the confidence she gained on the course”, where the following information identifies a specific kind of confidence.',checks:['Uncountable in this use.','General rather than specifically identified reference.'],trap:'An abstract noun can take the when the context makes its reference specific.',source:'grammar'},
{id:'g09',topic:'grammar',kind:'Choose and explain',q:'Fill the gaps and explain the choice.',example:'___ university lecturer\n___ honest reply',answer:'A university lecturer; an honest reply.',explain:'The choice depends on the next sound, not the next written letter. University begins with the consonant sound /j/. Honest begins with a vowel sound because the h is silent.',checks:['A before a consonant sound.','An before a vowel sound.'],trap:'“An before a vowel letter” is an incomplete rule.',source:'grammar'},
{id:'g10',topic:'grammar',kind:'Explain reference',q:'Why can the speaker use “the” the first time this noun appears?',example:'Please close the door. (Said in a classroom with one open door.)',answer:'The reference is identifiable from the shared situation.',explain:'A definite article does not require a previous mention. Speaker and listener can identify the intended door from their surroundings.',checks:['Definite article.','Shared situational knowledge makes the referent identifiable.'],trap:'“The is only used on second mention” is too narrow.',source:'grammar'},
{id:'g11',topic:'grammar',kind:'Form and reference',q:'Analyse “where” in this sentence.',example:'She studied in York, where she met her future colleague.',answer:'Where introduces a non-defining relative clause referring to York.',explain:'It is commonly described as a relative adverb (some teaching frameworks group it with relative pronouns). The clause adds information about the place and is separated by a comma; it does not identify which York is meant.',checks:['A relative item introducing a non-defining relative clause.','Refers back to York and adds information.'],trap:'Where is not a preposition. Be precise about the whole clause as well as the individual word.',source:'grammar'},
{id:'g12',topic:'grammar',kind:'Analyse a phrase',q:'What is the function of the whole phrase “from that point onwards”?',example:'The school opened in 2010. From that point onwards, enrolment grew.',answer:'An adverbial phrase of time.',explain:'The phrase sets the starting point for a continuing period. The word from is a preposition, but labelling only that word does not analyse the role of the entire phrase.',checks:['Adverbial of time.','A period beginning at the previously mentioned point.'],trap:'Do not apply the word class of the first word to the whole phrase.',source:'grammar'},
{id:'g13',topic:'grammar',kind:'Track the reference',q:'Analyse “there” in this context.',example:'We moved to Lisbon in May. We taught there for two years.',answer:'An adverb of place referring back to Lisbon.',explain:'There supplies a location and avoids repeating “in Lisbon”. This is anaphoric reference: it points back to information already given.',checks:['Adverb of place.','Anaphoric reference to Lisbon.'],trap:'This is not the introductory there in “There is a school nearby”.',source:'grammar'},
{id:'g14',topic:'grammar',kind:'Analyse the parts',q:'Analyse “in which” and identify what it refers to.',example:'She sent a letter in which she described her new course.',answer:'The preposition in + the relative pronoun which.',explain:'Which refers to a letter. The relative clause tells us what was contained in that letter. Naming both parts is more precise than calling the complete sequence a preposition.',checks:['In is a preposition; which is a relative pronoun.','The antecedent is a letter.'],trap:'A phrase containing a preposition is not itself a single preposition.',source:'grammar'},
{id:'g15',topic:'grammar',kind:'Countability in context',q:'Why does “experience” take different determiners here?',example:'A. Teaching abroad was an experience I will never forget.\nB. The job requires experience.',answer:'A is countable; B is uncountable.',explain:'A refers to one event or episode and uses a singular count noun with an. B refers to accumulated practical knowledge and uses an uncountable noun with no article here.',checks:['One episode versus accumulated knowledge.','Analyse countability in this particular use.'],trap:'Do not assign a noun one permanent countability label regardless of context.',source:'grammar'},
{id:'g16',topic:'grammar',kind:'Contrast meaning',q:'Do these instructions mean the same thing?',example:'You mustn’t bring a laptop.\nYou don’t have to bring a laptop.',answer:'No: prohibition versus absence of obligation.',explain:'Mustn’t says bringing a laptop is not permitted. Don’t have to says it is not necessary; bringing one may still be allowed.',checks:['Mustn’t = prohibited.','Don’t have to = not necessary.'],trap:'Negating an obligation can change the meaning in different ways depending on the form.',source:'grammar'},
{id:'m02',topic:'materials',kind:'Principle + reason',q:'A task supplies a model, then prompts, then removes the prompts. What learning principle could justify this?',answer:'Temporary support can help learners perform before they work independently.',explain:'The model and prompts scaffold the task. They reduce demands at first; withdrawing them gives learners a chance to apply the language with less support. Identify the actual model and prompts when using this argument.',checks:['Identify scaffolding and the support being removed.','Explain the transition to more independent performance.'],trap:'“The activity helps learning” gives no mechanism or evidence.',source:'teaching'},
{id:'m03',topic:'materials',kind:'Evidence + rationale',q:'Learners match new direction phrases to street diagrams. Give a learning assumption and a reason.',answer:'Visual context can help learners connect unfamiliar language with meaning.',explain:'The diagrams show the paths the phrases describe. Linking the words to a visible route can clarify meaning without a long verbal explanation. The evidence is the matching of phrases to diagrams.',checks:['State the principle about visual support.','Point to the diagrams and explain their function.'],trap:'Do not claim that every learner has a fixed “visual learning style”.',source:'teaching'},
{id:'m04',topic:'materials',kind:'Explain a technique',q:'Why might a short repetition drill help learners?',answer:'It gives supported practice of a particular spoken form.',explain:'Brief repetition lets learners concentrate on articulation and rhythm without inventing new content at the same time. The teacher can hear difficulties and give feedback. Later communicative practice is still needed.',checks:['A specific benefit for pronunciation or fluency of production.','A reason connected to reduced processing demands or feedback.'],trap:'Repeating a model does not prove that learners can use it spontaneously or understand it.',source:'teaching'},
{id:'m05',topic:'materials',kind:'Assumption or background?',q:'Improve this claim: “The learners already know some requests.”',answer:'New teaching can build on what learners can already do.',explain:'For example, an initial role-play can reveal which request forms learners use successfully. The teacher can then target missing or inaccurate forms rather than reteaching everything.',checks:['State a principle about building on existing ability.','Give evidence of elicitation or diagnosis.','Explain how it changes the teaching.'],trap:'An assumption about prior knowledge needs a learning implication to become a useful pedagogic principle.',source:'teaching'},
{id:'m06',topic:'materials',kind:'Complete the analysis',q:'Learners can recite a rule accurately but cannot recognise or use the expression in conversation. What may the lesson have neglected?',answer:'Meaning, pronunciation and appropriate use alongside form.',explain:'Knowing how a structure is assembled is only part of knowing it. Learners also need to connect it with intentions and contexts, recognise its spoken shape and practise using it for a purpose.',checks:['Distinguish knowledge of form from broader ability.','Include meaning/use and spoken realization.'],trap:'Explaining the rule again is not always the solution.',source:'teaching'},
{id:'m07',topic:'materials',kind:'Purpose versus procedure',q:'Turn this procedure into a purpose: “Learners fill six gaps with modal verbs.”',answer:'To provide controlled written practice of selecting the target modal forms.',explain:'The procedure says what happens. The purpose explains what the activity is intended to develop or check. If context forces a choice between meanings, it may also check understanding of those distinctions.',checks:['Name the type of practice.','Specify the target language or learning focus.'],trap:'Do not assume an exercise teaches new meanings if it only checks meanings already introduced.',source:'teaching'},
{id:'m08',topic:'materials',kind:'Link two exercises',q:'Explain how Exercise B builds on Exercise A.',example:'A. Complete requests using prompts.\nB. Write your own requests for three classroom situations.',answer:'B moves from controlled completion to less supported written production.',explain:'A supplies much of the language. In B, learners choose the wording themselves while reusing the request forms from A. The relationship is a change in support and freedom, not just “more practice”.',checks:['Name both exercises.','Explain what changes and what language is carried forward.'],trap:'Describing B alone does not explain how B combines with A.',source:'teaching'},
{id:'m09',topic:'materials',kind:'Receptive or productive?',q:'What changes between these pronunciation exercises?',example:'1. Listen and identify the phrase you hear.\n2. Say the phrase to a partner who chooses its matching picture.',answer:'The focus moves from recognising spoken language to producing it.',explain:'Exercise 1 is receptive: learners distinguish what they hear. Exercise 2 is productive: they articulate the phrase so a listener can interpret it. Both involve the same language, but they place different demands on learners.',checks:['Listening recognition versus spoken production.','Explain the relationship using the same target language.'],trap:'Do not call a listen-only task controlled oral production.',source:'teaching'},
{id:'m10',topic:'materials',kind:'Check the evidence',q:'Can you justify “collaboration supports learning” from this instruction alone?',example:'Read each sentence and underline the time expression.',answer:'No. The instruction does not show collaboration.',explain:'A sound pedagogic principle must be visible in the actual task. Pair comparison, a shared decision or an explicit group task would provide evidence of collaboration. Do not invent an interaction pattern.',checks:['Recognise that the evidence is missing.','Name what evidence would support the principle.'],trap:'A memorised list of learning theories cannot replace analysis of the materials.',source:'teaching'},
{id:'m11',topic:'materials',kind:'Choose a precise purpose',q:'When is “guided discovery” an appropriate description?',example:'A. Apply an already supplied rule to ten sentences.\nB. Compare examples and answer questions that lead you to infer the rule.',answer:'B supports guided discovery.',explain:'The questions guide learners to work out a generalisation from examples. A may be useful practice, but applying a supplied rule is not the same process as discovering it.',checks:['Infer a rule or pattern from examples.','Identify how the questions guide the inference.'],trap:'Not every exercise involving thought or guessing is guided discovery.',source:'teaching'},
{id:'m12',topic:'materials',kind:'Meaningful practice',q:'Why is a guessing task different from simply reading sentences aloud?',example:'Learners describe rules for an unnamed place. Their partners identify the place.',answer:'The listeners need to understand the meaning to complete the task.',explain:'The missing information creates a communicative purpose. Speakers choose clues and listeners interpret them, possibly asking for clarification. The activity can connect target forms with an intended message.',checks:['Identify the information gap or communicative purpose.','Explain what speakers and listeners must do.'],trap:'“It is fun” may be true, but does not explain the language-learning opportunity.',source:'teaching'},
{id:'p02',topic:'pronunciation',kind:'Link two words',q:'What can connect these words in a non-rhotic accent?',example:'far away',answer:'Linking /r/: /fɑːrəˈweɪ/.',explain:'In a non-rhotic accent, far in isolation need not have a final /r/. Before the vowel in away, the written r can be pronounced to link the words. Rhotic accents already pronounce that r.',checks:['Name linking /r/.','Locate it between far and away.','Specify the accent condition.'],trap:'Do not present one accent’s connected-speech pattern as universal.',source:'grammar'},
{id:'p03',topic:'pronunciation',kind:'Name and locate',q:'Identify a possible sound change in casual speech.',example:'next day → /neks deɪ/',answer:'Elision of /t/ in the consonant cluster.',explain:'The /t/ in next may be omitted before the following /d/. This is a possible realization, not a requirement. Identify both the omitted sound and the location.',checks:['Elision.','The /t/ of next, before day.'],trap:'“The words are spoken quickly” does not identify a phonological feature.',source:'grammar'},
{id:'p04',topic:'pronunciation',kind:'Name the process',q:'What happens when the /n/ in “green park” sounds more like /m/?',answer:'Assimilation of place of articulation.',explain:'The alveolar nasal /n/ may become bilabial /m/ before the bilabial /p/. A sound changes to become more like its neighbour; it is not merely deleted.',checks:['Name assimilation.','Specify /n/ → /m/ before /p/.'],trap:'Assimilation changes a sound; elision omits a sound.',source:'grammar'},
{id:'p05',topic:'pronunciation',kind:'Link the boundary',q:'What can make the boundaries less obvious in this phrase?',example:'pick it up',answer:'Consonant-to-vowel linking, also called catenation.',explain:'The final /k/ connects smoothly with the vowel in it, and /t/ connects with the vowel in up. The words can form a continuous sequence /pɪkɪtʌp/ rather than three isolated units.',checks:['Consonant-to-vowel linking.','Locate pick‿it and it‿up.'],trap:'Linking does not mean the words become one grammatical word.',source:'grammar'},
{id:'p06',topic:'pronunciation',kind:'Linking glide',q:'What glide may be heard between these words?',example:'go out',answer:'A possible /w/ glide between the vowel sounds.',explain:'The rounded ending of go can lead into the next vowel through a /w/-like transition: approximately /ɡəʊwaʊt/ in one common British pronunciation. Accent and speaking style affect the realization.',checks:['Identify /w/.','Place it between go and out.'],trap:'Avoid inventing a /w/ where the vowel sequence does not support it.',source:'grammar'},
{id:'p07',topic:'pronunciation',kind:'Weak versus strong',q:'Why might “can” sound different in these two replies?',example:'A. I can swim. (Neutral statement.)\nB. Yes, I CAN. (Emphatic correction.)',answer:'Unstressed can may be /kən/; emphatic can uses /kæn/.',explain:'The weak form reduces the vowel to schwa. Contrastive emphasis can require the strong vowel. Function words are not permanently unstressed.',checks:['Weak /kən/ versus strong /kæn/.','Explain the role of emphasis.'],trap:'“All modal verbs are always stressed” and “all function words are always weak” are both too broad.',source:'grammar'},
{id:'p08',topic:'pronunciation',kind:'Correct the explanation',q:'Is “you are” becoming “you’re” best described as deleting the verb from the sentence?',answer:'No. It is a contraction; the grammatical meaning remains.',explain:'You’re represents a contracted form of you are. Its sound may also be reduced in connected speech, but this is different from claiming that the sentence no longer contains the verb be.',checks:['Identify contraction.','Distinguish sound reduction from loss of grammatical meaning.'],trap:'A weak sound can be hard to hear without being grammatically absent.',source:'grammar'},
{id:'t02',topic:'terms',kind:'Retrieve the term',q:'What kind of test asks learners to perform the skill being assessed?',example:'To assess speaking, learners conduct a short spoken interview.',answer:'A direct test.',explain:'The learner performs the target skill itself. An indirect measure might infer speaking ability from another kind of task, such as selecting grammatical sentences on paper.',checks:['Recall direct test.','Connect the test task to the target skill.'],trap:'“Role-based test” is not the established term for this distinction.',source:'terms'},
{id:'t03',topic:'terms',kind:'Expand the acronym',q:'What does CLIL stand for, and what is its dual focus?',answer:'Content and Language Integrated Learning.',explain:'Learners study subject content through an additional language, with attention to both the subject and language learning. For example, a science unit can develop knowledge of ecosystems alongside the English needed to discuss them.',checks:['Expand all four words accurately.','Identify content and language learning together.'],trap:'Simply replacing one acronym letter changes the answer; retrieve CLIL exactly.',source:'terms'},
{id:'t04',topic:'terms',kind:'Retrieve the term',q:'How is “arrived” classified in this sentence?',example:'The guests arrived after lunch.',answer:'Intransitive: it has no direct object.',explain:'“After lunch” tells us when the arrival happened; it is an adverbial, not an object. Compare a transitive use such as “The guests opened the door”, where the door is the direct object.',checks:['Intransitive.','No direct object in this use.'],trap:'A phrase after a verb is not automatically its object.',source:'terms'},
{id:'t05',topic:'terms',kind:'Distinguish terms',q:'What precise term describes “flour” and “flower” in accents where they sound the same?',answer:'Homophones.',explain:'They share a pronunciation but differ in meaning and spelling. Homonym is used with different breadth in different frameworks; homophone is the precise term for this sound relationship.',checks:['Homophones.','Same pronunciation; different meaning and spelling here.'],trap:'Use the most specific established term the definition asks for.',source:'terms'},
{id:'t06',topic:'terms',kind:'Define + exemplify',q:'Define genre and give a language-teaching example.',answer:'A recognisable type of spoken or written text associated with a purpose and conventions.',explain:'For example, a restaurant review typically evaluates food, service and the overall experience. Genre concerns what kind of text it is, not which exercise learners do with it.',checks:['A text type with communicative purpose and conventions.','An example such as a review, report or job interview.'],trap:'“Listening for gist” is a task or listening focus, not a genre.',source:'terms'},
{id:'t07',topic:'terms',kind:'Complete the definition',q:'What makes a proficiency test different from a course achievement test?',answer:'It assesses ability independently of a particular course syllabus.',explain:'A proficiency test asks what someone can do with the language against a broader standard or purpose. An achievement test checks learning against specified course content. An exam name alone does not explain this difference.',checks:['General or purpose-related language ability.','Independence from a particular course of study.'],trap:'“An official language exam” does not distinguish proficiency from achievement.',source:'terms'},
{id:'t08',topic:'terms',kind:'Define + exemplify',q:'Define a compound word and analyse “toothbrush”.',answer:'A lexical item formed by combining two or more bases.',explain:'Toothbrush combines tooth + brush. Compounds may be written solid, hyphenated or as separate words; spelling alone does not determine compound status.',checks:['Two or more bases combined into a lexical item.','Tooth + brush.'],trap:'Adding an inflection or a suffix to a single base is not by itself compounding.',source:'terms'},
{id:'t09',topic:'terms',kind:'Define + exemplify',q:'What is a stative verb? Give an example in a sentence.',answer:'A verb used to describe a state rather than a dynamic event.',explain:'“I own a bicycle” describes possession. Many stative uses do not normally occur in the progressive, but some verbs have both stative and dynamic senses: compare “I think you are right” and “I am thinking about it”.',checks:['State rather than dynamic event.','A clear example such as own in a possession sense.'],trap:'“Stative verbs can never be progressive” is too absolute.',source:'terms'},
{id:'t10',topic:'terms',kind:'Describe articulation',q:'What is an affricate? Give an English example.',answer:'A consonant with a complete closure followed by a frictional release.',explain:'Airflow is first blocked and then released through a narrow opening. English /tʃ/ as in chair and /dʒ/ as in joke are affricates.',checks:['Closure followed by friction.','An appropriate phoneme and word example.'],trap:'A fricative has friction but does not begin with the same complete closure phase.',source:'terms'},
{id:'v02',topic:'testing',kind:'Distinguish concepts',q:'Two markers give the same speaking performance very different scores. Which quality is directly in question?',answer:'Inter-rater reliability.',explain:'The concern is consistency across assessors. A shared scale, sample performances and marker training can reduce disagreement. This does not automatically establish that the test measures the right ability.',checks:['Consistency between different raters.','A relevant response such as calibration or training.'],trap:'Reliability and validity are related, but they are not interchangeable.',source:'teaching'},
{id:'v03',topic:'testing',kind:'Evaluate validity',q:'A course aims at informal spoken interaction, but the final test only uses written grammar choices. What is the concern?',answer:'The assessment underrepresents the intended ability.',explain:'The results say little directly about managing turns, responding to others or speaking intelligibly. A test can be marked consistently while providing insufficient evidence for its intended interpretation.',checks:['Mismatch between target ability and assessed tasks.','Explain what evidence is missing.'],trap:'Easy marking does not compensate for failing to assess the target skill.',source:'teaching'},
{id:'v04',topic:'testing',kind:'Evaluate in context',q:'What is one benefit and one qualification when a diagnostic listening test plays a recording twice?',answer:'A second hearing offers another chance to process the message; suitability depends on the target ability.',explain:'It may reduce the effect of a brief lapse of attention. But if the intended interpretation concerns understanding one-time announcements, two hearings change the conditions. Evaluate the design against the diagnostic purpose.',checks:['A plausible benefit for demonstrating comprehension.','Relate the judgment to the intended listening situation.'],trap:'“Twice is always more authentic” or “twice guarantees understanding” goes too far.',source:'teaching'},
{id:'v05',topic:'testing',kind:'Spot a confound',q:'A listening test uses long, complex written questions for elementary learners. What may distort the result?',answer:'Reading demands may interfere with the measurement of listening.',explain:'A learner may understand the recording but misread the question. The score then reflects more than the intended listening ability. Simplifying the written prompts may make the evidence easier to interpret.',checks:['Identify the extra reading burden.','Explain why a low score may misrepresent listening ability.'],trap:'Name the effect on the interpretation, not merely that the questions are difficult.',source:'teaching'},
{id:'v06',topic:'testing',kind:'Evaluate scoring',q:'A learner hears “Thursday” correctly but misspells it in a listening gap. What should the marker consider?',answer:'The scoring policy and the ability the test is intended to assess.',explain:'If the aim is listening comprehension alone, rejecting an unmistakable transcription solely for spelling may introduce an unwanted writing demand. If accurate written recording is part of the target task, spelling may legitimately matter.',checks:['Refer to the target construct and stated policy.','Explain the possible effect of spelling on the listening score.'],trap:'Do not assume spelling must always count, or must never count.',source:'teaching'},
{id:'v07',topic:'testing',kind:'Make a point specific',q:'Improve “The test is easy, so it is good.”',answer:'Judge whether the difficulty suits the learners and diagnostic purpose.',explain:'For example: familiar everyday vocabulary may allow A2 learners to demonstrate listening rather than struggle mainly with unfamiliar lexis. If every item is trivial, however, the test may reveal little about differences in their needs.',checks:['Name a relevant feature and learner level.','Explain its consequence for useful evidence.'],trap:'Confidence is valuable, but a test still needs to reveal something about ability.',source:'teaching'},
{id:'v08',topic:'testing',kind:'Point + consequence',q:'Complete the evaluation: “All answers are numbers or single words…”',answer:'…so a clear answer key can make scoring more consistent.',explain:'With accepted variants specified, different markers are more likely to award the same score. However, this tells us about scoring consistency, not whether the small sample covers enough listening skills.',checks:['Link the feature to scorer consistency.','Keep the claim separate from coverage or validity.'],trap:'“Objective” scoring does not make every aspect of a test effective.',source:'teaching'},
{id:'e02',topic:'exam',kind:'Avoid duplicate points',q:'Are these three distinct genre features of a biography?',example:'Birthplace, childhood home, first workplace.',answer:'They are likely examples of one broader feature: factual life details.',explain:'For broader coverage, look across content, organisation, grammar, lexis and layout. For example, chronological sequencing and narrative tense use analyse different dimensions from factual content.',checks:['Recognise the potential overlap.','Choose genuinely different dimensions for additional features.'],trap:'Three different facts do not necessarily earn three separate feature marks.',source:'exam'},
{id:'e03',topic:'exam',kind:'Choose distinct features',q:'For a childhood-memory speaking task, suggest three different language areas, each with an example.',answer:'Past-reference forms, question forms and language for inviting a contribution.',explain:'Past reference: “I was visiting my aunt when I learned to swim.”\nQuestion form: “What did you enjoy most?”\nInviting a contribution: “How about you, Sam?”\nUse precise labels and examples that fit the level and activity.',checks:['Three distinguishable areas.','A complete, task-specific example for each.'],trap:'Listing three past verb forms as three separate features can repeat the same area.',source:'exam'},
{id:'e04',topic:'exam',kind:'Support a diagnosis',q:'Which gives a stronger analysis of learner writing?',example:'A. The vocabulary is bad.\nB. Lexical accuracy: an inappropriate verb–noun collocation, “make a photo”, where “take a photo” is intended.',answer:'B names a precise issue and supplies evidence.',explain:'An evaluative label such as good or bad is not a linguistic diagnosis. Identify the relevant area, specify the pattern and give an example that actually illustrates it. A correction can clarify the intended target.',checks:['Name a specific feature, not just the broad criterion.','Provide a matching example.'],trap:'One isolated mistake does not automatically establish a frequent or key weakness.',source:'teaching'},
{id:'e05',topic:'exam',kind:'Develop a balanced answer',q:'Give two different ways teacher talk can support learning.',answer:'Provide accessible language input, and guide learning through questions or feedback.',explain:'A short demonstration can model a useful expression in context. A follow-up question can push learners to explain an idea more clearly; feedback can help them notice a gap. These are distinct purposes, not an argument for talking continuously.',checks:['Two distinct benefits.','A specific example or learning mechanism for each.'],trap:'Listening involves active interpretation. Do not dismiss it as inherently passive.',source:'teaching'},
{id:'e06',topic:'exam',kind:'Use the remaining time',q:'You have spare time after a short answer to a high-mark discussion task. What should you check first?',answer:'Breadth, support and whether every part of the question is answered.',explain:'Look for missing distinct points, then add a reason or concrete classroom example where it clarifies a claim. Remove repetition and check terminology. Give the most attention to gaps in the tasks carrying the most marks.',checks:['Check both coverage and development.','Add new substance rather than longer wording.','Use the marks and instructions to guide effort.'],trap:'Finishing early is not the goal if your answer leaves relevant knowledge unexpressed.',source:'exam'}
];
